    def evalRPN(self, tokens: List[str]) -> int:
        pop_list = []
        for i in tokens:
            if i in "+-*/":
                tmp1 = pop_list.pop()
                tmp2 = pop_list.pop()
                pop_list.append(str(int(eval(tmp2+i+tmp1)))) # eval函数
            else:
                pop_list.append(i)
        return int(pop_list[0])

