class Solution {
public:
    int evalRPN(vector<string>& tokens) {
        stack<int> stk;
        for(auto it:tokens)
        {
            string s=it;
            if(s.size()>1 or isdigit(s[0])) //The s.size() > 1, accounts for negative numbers, because there the first character will be a minus not a digit.
                stk.push(stoi(s));
            else
            {
                char ch=it[0];
                long long int s=stk.top();
                stk.pop();
                long long int f=stk.top();
                stk.pop();
                if(ch=='*')
                    f*=s;
                if(ch=='/')
                    f/=s;
                if(ch=='-')
                    f-=s;
                if(ch=='+')
                    f+=s;
                stk.push(f);
            } 
        }
        return stk.top();
    }
};

class Solution(object):
    def evalRPN(self, tokens):
        """
        :type tokens: List[str]
        :rtype: int
        """
        stack = []
        for token in tokens:
            if token not in "+-*/":
                stack.append(int(token))
            else:
                b = stack.pop()
                a = stack.pop()
                if token=="+":
                    stack.append(a+b)
                elif token=="-":
                    stack.append(a-b)
                elif token=="*":
                    stack.append(a*b)
                else:
                    if a*b < 0:
                        stack.append(-(abs(a)/abs(b)))
                    else:
                        stack.append(a/b)
        return stack[0]

class Solution(object):
    def evalRPN(self, tokens):
        """
        :type tokens: List[str]
        :rtype: int
        """
        stack = []
        for token in tokens:
            if token in ["+", "-", "*", "/"]:
                num1 = stack.pop()
                num2 = stack.pop()
                if token == "+":
                    stack.append(num2 + num1)
                elif token == "-":
                    stack.append(num2 - num1)
                elif token == "*":
                    stack.append(num2 * num1)
                else:
                    stack.append(int(float(num2) / float(num1)))
            else:
                stack.append(int(token))
        return stack[-1]
